"""Create a portable classic-script bundle. No packages or network required."""
from pathlib import Path
import re

root = Path(__file__).resolve().parent.parent
parts = []
for name in ("data.js", "core.js", "app.js"):
    source = (root / "dist" / name).read_text()
    source = re.sub(r"^import .*?;\n", "", source, flags=re.MULTILINE)
    source = re.sub(r"^export ", "", source, flags=re.MULTILINE)
    parts.append(source)
(root / "dist" / "bundle.js").write_text(
    "// Generated by scripts/build.py. Edit app.js, core.js, and data.js instead.\n"
    + "(() => {\n'use strict';\n" + "\n".join(parts) + "\n})();\n"
)
print("Built dist/bundle.js")
